-- recorded_at is actual normalized availability; never backfill it from historical market/receipt time.
ALTER TABLE mkt.trades ADD COLUMN IF NOT EXISTS recorded_at timestamptz;
ALTER TABLE mkt.trades ADD COLUMN IF NOT EXISTS received_ts timestamptz;
CREATE INDEX mkt_trades_availability_time_key ON mkt.trades(recorded_at,"ts",storage_key) WHERE recorded_at IS NOT NULL;
CREATE INDEX mkt_trades_identity_availability ON mkt.trades("instrument_id",recorded_at,"ts",storage_key) WHERE recorded_at IS NOT NULL;
